import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Second {
    private static class InputReader {
        private InputStream stream;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            try {
                return stream.read();
            } catch (IOException e) {
                throw new InputMismatchException();
            }
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                if (c == -1) throw new InputMismatchException();
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                if (c == -1) throw new InputMismatchException();
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }
    }

    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int n = in.readInt();
        String st = in.readString();
        String part = st.substring(0, n);

        int a1 = 0;
        String outside = part.replaceAll("\\([^)]*\\)?", "_");
        for (String token : outside.split("_")) {
            if (token.length() > a1) a1 = token.length();
        }

        int a2 = 0;
        Pattern p = Pattern.compile("\\(([^)]*)\\)?");
        Matcher m = p.matcher(part);
        while (m.find()) {
            if (m.group(1).length() > 0) a2++;
        }

        out.println(a1 + " " + a2);
        out.close();
    }
}
